Here is a C++ function that uses the `pugixml` library to convert markdown to HTML:
```cpp
#include <pugixml.hpp>
#include <string>

std::string markdown_to_html(const std::string& markdown) {
    pugi::xml_document doc;
    pugi::xml_parse_result result = doc.load_string(markdown.c_str());
    if (!result) {
        // handle parsing error
        return "";
    }

    pugi::xml_node root = doc.document_element();
    std::string html;
    pugi::xml_node node;
    for (node = root.first_child(); node; node = node.next_sibling()) {
        if (node.type() == pugi::node_element) {
            html += node.name() + ">";
            for (pugi::xml_node child = node.first_child(); child; child = child.next_sibling()) {
                if (child.type() == pugi::node_text) {
                    html += child.text().get();
                } else if (child.type() == pugi::node_element) {
                    html += "<" + child.name() + ">" + markdown_to_html(child.text().get()) + "</" + child.name() + ">";
                }
            }
            html += "</" + node.name() + ">";
        }
    }

    return html;
}
```
This function uses the `pugixml` library to parse the markdown text and convert it to an XML document. It then iterates over the XML nodes and constructs the HTML output.

You can use this function like this:
```cpp
int main() {
    std::string markdown = "# Hello World\nThis is a **bold** text.";
    std::string html = markdown_to_html(markdown);
    std::cout << html << std::endl;
    return 0;
}
```
