Here is a JavaScript function that checks if any of the numbers in the input array are prime numbers:
```javascript
function checkPrimes(numbers) {
  // Check if the input array has exactly 5 elements
  if (numbers.length !== 5) {
    throw new Error("Input array must have exactly 5 elements");
  }

  // Iterate over each number in the array
  for (let i = 0; i < numbers.length; i++) {
    const num = numbers[i];

    // Check if the number is less than 2 (not prime)
    if (num < 2) {
      continue;
    }

    // Check if the number is divisible by any number up to its square root
    for (let j = 2; j <= Math.sqrt(num); j++) {
      if (num % j === 0) {
        // If the number is divisible, it's not prime
        continue;
      }
    }

    // If we reach this point, the number is prime
    console.log(`Found prime number: ${num}`);
  }
}

// Example usage:
const numbers = [1, 2, 3, 4, 5];
checkPrimes(numbers);
```
